// Taudot's mark: the tau (TeX) leaning after the dot (you). A drop-in SwiftUI view, no assets needed.
// Geometry matches docs/design/logo/final/mark.svg (generated by docs/design/logo/build_final.py).
// Use: TaudotMark().foregroundStyle(.primary).frame(height: 28), or TaudotMark(dot: .coral) for the brand colour.
// Any foreground style works, translucent ones included: the tau is one outline filled once, so the bar and stem
// never double up where they cross (and with no dot colour, the dot joins that same outline).
import SwiftUI

public struct TaudotMark: View {
  /// The dot's colour; nil draws it in the foreground style like the tau.
  public var dot: Color?
  public init(dot: Color? = nil) { self.dot = dot }

  /// The brand coral: the dot is "you", the only warm colour in the brand.
  public static let coral = Color(red: 1.0, green: 0.369, blue: 0.302)
  /// The mark's box in the 1024 icon grid (mark.svg's viewBox).
  static let box = CGRect(x: 149, y: 190, width: 823, height: 670)

  public var body: some View {
    ZStack {
      if let dot {
        Glyph(parts: .tau).fill(.foreground)
        Glyph(parts: .dot).fill(dot)
      } else {
        Glyph(parts: .both).fill(.foreground)
      }
    }
    .aspectRatio(Self.box.width / Self.box.height, contentMode: .fit)
    .accessibilityElement()
    .accessibilityLabel("Taudot")
  }

  /// The mark's outlines in the 1024 grid, fitted to a rect.
  struct Glyph: Shape {
    enum Parts { case tau, dot, both }
    var parts: Parts

    /// The tau as one outline: both strokes expanded and unioned, so a single fill covers each pixel once.
    static let tau: Path = {
      // build9's LEAN: rotate 12 degrees about (520, 760), then shift (-110, -10).
      let lean = CGAffineTransform(translationX: -520, y: -760)
        .concatenating(CGAffineTransform(rotationAngle: 12 * .pi / 180))
        .concatenating(CGAffineTransform(translationX: 520 - 110, y: 760 - 10))
      var bar = Path()
      bar.move(to: CGPoint(x: 262, y: 420))
      bar.addCurve(to: CGPoint(x: 400, y: 300), control1: CGPoint(x: 270, y: 330), control2: CGPoint(x: 320, y: 300))
      bar.addLine(to: CGPoint(x: 770, y: 300))
      var stem = Path()
      stem.move(to: CGPoint(x: 560, y: 330))
      stem.addCurve(to: CGPoint(x: 600, y: 680), control1: CGPoint(x: 552, y: 480), control2: CGPoint(x: 552, y: 590))
      stem.addCurve(to: CGPoint(x: 760, y: 744), control1: CGPoint(x: 636, y: 748), control2: CGPoint(x: 700, y: 760))
      func outline(_ p: Path, _ width: CGFloat) -> CGPath {
        p.applying(lean).cgPath.copy(strokingWithWidth: width, lineCap: .round, lineJoin: .round, miterLimit: 10)
      }
      return Path(outline(bar, 150).union(outline(stem, 142)))
    }()
    static let dot = Path(ellipseIn: CGRect(x: 836 - 132, y: 628 - 132, width: 264, height: 264))

    func path(in rect: CGRect) -> Path {
      let box = TaudotMark.box
      let s = min(rect.width / box.width, rect.height / box.height)
      let fit = CGAffineTransform(a: s, b: 0, c: 0, d: s,
                                  tx: rect.midX - box.midX * s, ty: rect.midY - box.midY * s)
      let p: Path
      switch parts {
      case .tau: p = Self.tau
      case .dot: p = Self.dot
      case .both: p = Path(Self.tau.cgPath.union(Self.dot.cgPath))
      }
      return p.applying(fit)
    }
  }
}
